def group_by_parity_preserve_order(nums):
    result = {'even': [], 'odd': []}
    for x in nums:
        if x % 2 == 0:
            result['even'].append(x)
        else:
            result['odd'].append(x)
    return result

def k_closest_to_target(nums, target, k):
    selected = sorted(nums, key=lambda x: (abs(x - target), x))[:k]
    return sorted(selected)

def second_smallest_unique(nums):
    distinct = sorted(set(nums))
    return distinct[1]

def top_k_leaderboard_names(entries, k):
    sorted_entries = sorted(entries, key=lambda e: (-e[1], e[0]))
    return [name for name, score in sorted_entries[:k]]

def median_lower(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return s[n // 2 - 1]
